components.css:
.ds-action-primary { background: #38bdf8; color: #1a0d0d; border: 0; border-radius: 5px;
  width: 112px; height: 30px; font: 700 11px system-ui, sans-serif; letter-spacing: 0.02em; cursor: pointer; }
.ds-action-primary:hover { box-shadow: 0 0 0 2px {c1} inset; }
.ds-action-primary:focus-visible { outline: 1px solid #38bdf8; outline-offset: 3px; }

.ds-action-secondary { background: #332024; color: #f3e8e0; border: 0; border-radius: 5px;
  width: 112px; height: 30px; font: 400 11px system-ui, sans-serif; cursor: pointer; }
.ds-action-secondary:hover { background: #4a2c2f; }
.ds-action-secondary:focus-visible { outline: 1px solid #38bdf8; outline-offset: 3px; }

.ds-chip { background: #332024; color: #f3e8e0; border: 0; border-radius: 3px;
  height: 24px; padding: 0 12px; font: 400 10px system-ui, sans-serif; cursor: pointer; }
.ds-chip:hover { background: #4a2c2f; }
.ds-chip--on { background: {c1}; color: #1a0d0d; }
.ds-chip:focus-visible { outline: 1px solid #38bdf8; outline-offset: 2px; }

.ds-param { position: relative; display: flex; align-items: center; justify-content: space-between;
  height: 25px; padding: 0 8px; border-radius: 4px; background: #332024; overflow: hidden;
  font: 400 11px system-ui, sans-serif; color: #f3e8e0; }
.ds-param i { position: absolute; inset: 0 auto 0 0; background: {c1}; opacity: 0.3; }
.ds-param span { position: relative; }
.ds-param:hover { box-shadow: 0 0 0 1px #4a3134 inset; }

.ds-card { background: #221416; color: #f3e8e0; border: 1px solid #4a3134; border-radius: 4px; padding: 8px; }
.ds-card strong { display: block; font: 700 10px system-ui, sans-serif; letter-spacing: 0.5px; color: #b09a94; }
.ds-card p { margin: 6px 0 0; font: 400 11px system-ui, sans-serif; color: #b09a94; }

.ds-input { background: #332024; color: #f3e8e0; border: 1px solid #4a3134; border-radius: 4px;
  height: 25px; padding: 0 8px; font: 400 11px system-ui, sans-serif; text-align: right; width: 120px; }
.ds-input:focus { outline: none; border-color: #38bdf8; box-shadow: 0 0 0 1px #38bdf8 inset; }
